import csv

totals = {}
with open('records.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        region = row['region']
        qty = int(row['qty'])
        price = int(row['price'])
        if region not in totals:
            totals[region] = 0
        totals[region] += qty * price

if totals:
    max_total = max(totals.values())
    print(max_total)
else:
    print(0)
